mapper.select:
SELECT * FROM (
    SELECT ROWNUM AS rn, a.* FROM (
        /* 💡 이름별로 그룹화하여 중복을 제거하고 가장 최신 데이터 위주로 정렬 */
        SELECT 
            DANGER_NAME,
            MIN(DANGER_ID) AS DANGER_ID,
            MAX(DANGER_DATE) AS DANGER_DATE
        FROM DANGER_DETAIL


                AND DANGER_NAME LIKE '%' || #{keyword} || '%'


        GROUP BY DANGER_NAME
        ORDER BY DANGER_ID DESC
    ) a WHERE ROWNUM <= #{endRow}
) WHERE rn >= #{startRow}

mapper.update:
UPDATE DANGER_DETAIL
SET 
    DANGER_NAME = #{dangerName}
WHERE DANGER_ID = #{dangerId}
